-- Backend Engineering ("The Fracture") Act 14 -- "GraphQL District" content.
-- Opens Arc III (Connect). 1 campaign, 2 operations, 12 missions (11 lessons + boss),
-- following the same campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every prior Act.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-be14', 'world-be-14', 'graphql-district', '14A - GraphQL District', 'Three mobile screens need three different combinations of the same underlying data, and REST has grown nineteen slightly-different endpoints trying to serve them. Arc III opens with a language built to ask for exactly the shape you need, in one request.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-be14-1', 'campaign-be14', 'shaping-the-graph', 'Shaping the Graph', 'Why GraphQL exists, how a schema describes a graph of types, and the queries, mutations and resolvers that make it real.', 1),
  ('operation-be14-2', 'campaign-be14', 'production-graphql', 'Production GraphQL', 'Variables, fragments, interfaces, pagination, the N+1 problem and DataLoader, and the safeguards a public schema actually needs in production.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-be14-01', 'world-be-14', 'campaign-be14', 'operation-be14-1', 'why-graphql', 'Why GraphQL?', 'Three mobile screens need three different combinations of the same underlying data. REST answered that by growing nineteen slightly-different endpoints. Arc III opens with a different answer entirely.', 'intermediate', ARRAY['mira','forge'], null, null, '{"type":"simulation","simulationId":"why-graphql-sim"}'::jsonb, '{"xp":190,"credits":35}'::jsonb, false, 1),
  ('mission-be14-02', 'world-be-14', 'campaign-be14', 'operation-be14-1', 'graphql-schema', 'GraphQL Schema', 'Every GraphQL API starts from one document: the schema. It declares every type, every field, and every operation that''s allowed to exist -- nothing reaches a resolver that the schema didn''t already promise.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be14-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"graphql-schema-sim"}'::jsonb, '{"xp":194,"credits":35}'::jsonb, false, 2),
  ('mission-be14-03', 'world-be-14', 'campaign-be14', 'operation-be14-1', 'object-types', 'Object Types', 'An object type is a named shape with fields, each field typed all the way down to a scalar. Nest object types inside each other and you''ve modeled the graph a client will actually traverse.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be14-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"object-types-sim"}'::jsonb, '{"xp":198,"credits":36}'::jsonb, false, 3),
  ('mission-be14-04', 'world-be-14', 'campaign-be14', 'operation-be14-1', 'queries', 'Queries', 'A query is a client stating, in the shape of the schema itself, exactly which fields it wants back -- and nothing it doesn''t.', 'intermediate', ARRAY['forge'], '{"requiredMissionIds":["mission-be14-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"graphql-queries-sim"}'::jsonb, '{"xp":202,"credits":36}'::jsonb, false, 4),
  ('mission-be14-05', 'world-be-14', 'campaign-be14', 'operation-be14-1', 'mutations', 'Mutations', 'Queries read. Mutations write -- and GraphQL makes that split explicit in the schema itself, so nothing that changes data can hide behind what looks like a harmless read.', 'intermediate', ARRAY['mira'], '{"requiredMissionIds":["mission-be14-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"mutations-sim"}'::jsonb, '{"xp":206,"credits":37}'::jsonb, false, 5),
  ('mission-be14-06', 'world-be-14', 'campaign-be14', 'operation-be14-1', 'resolvers', 'Resolvers', 'The schema describes what''s possible. A resolver is the function that actually goes and gets one field''s value -- and every field, nested at any depth, has one.', 'intermediate', ARRAY['forge','mira'], '{"requiredMissionIds":["mission-be14-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"resolvers-sim"}'::jsonb, '{"xp":210,"credits":38}'::jsonb, false, 6),
  ('mission-be14-07', 'world-be-14', 'campaign-be14', 'operation-be14-2', 'variables-and-fragments', 'Variables and Fragments', 'A hardcoded query string works exactly once. Variables let the same query run with different arguments. Fragments let the same field selection get reused instead of copy-pasted across every query that needs it.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be14-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"variables-fragments-sim"}'::jsonb, '{"xp":212,"credits":38}'::jsonb, false, 7),
  ('mission-be14-08', 'world-be-14', 'campaign-be14', 'operation-be14-2', 'interfaces-and-unions', 'Interfaces and Unions', 'Not every field returns one predictable type. An interface guarantees a shared set of fields across several types. A union says the result could be any one of several types entirely, with nothing shared at all.', 'advanced', ARRAY['mira'], '{"requiredMissionIds":["mission-be14-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"interfaces-unions-sim"}'::jsonb, '{"xp":216,"credits":39}'::jsonb, false, 8),
  ('mission-be14-09', 'world-be-14', 'campaign-be14', 'operation-be14-2', 'graphql-pagination', 'GraphQL Pagination', 'A list field that returns everything at once has the same problem a REST list endpoint did. GraphQL''s answer -- edges, nodes, cursors, pageInfo -- is cursor pagination wearing the schema''s own vocabulary.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be14-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"graphql-pagination-sim"}'::jsonb, '{"xp":220,"credits":40}'::jsonb, false, 9),
  ('mission-be14-10', 'world-be-14', 'campaign-be14', 'operation-be14-2', 'n-plus-1-and-dataloader', 'N+1 and DataLoader', 'A query for 20 permits, each resolving its own applicant separately, fires 21 database queries for data that could have been fetched in two. The N+1 problem is resolvers doing exactly what they were told, one at a time.', 'advanced', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be14-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"n-plus-1-dataloader-sim"}'::jsonb, '{"xp":224,"credits":41}'::jsonb, false, 10),
  ('mission-be14-11', 'world-be-14', 'campaign-be14', 'operation-be14-2', 'authentication-and-query-complexity', 'Authentication and Query Complexity', 'Authenticating a GraphQL request is the easy half. The harder half: a schema that lets a client compose a request cheap to send and expensive to run -- and nothing stopping them yet.', 'advanced', ARRAY['forge'], '{"requiredMissionIds":["mission-be14-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"auth-query-complexity-sim"}'::jsonb, '{"xp":228,"credits":42}'::jsonb, false, 11),
  ('mission-be14-12', 'world-be-14', 'campaign-be14', 'operation-be14-2', 'the-infinite-query', 'The Infinite Query', 'A client built entirely from the public schema found a self-referencing field and recursed without bound. No exploit, no malicious intent -- just a graph that was always shaped to allow it, and nothing that ever said stop.', 'boss', ARRAY['mira','forge'], '{"requiredMissionIds":["mission-be14-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"infinite-query-boss-sim"}'::jsonb, '{"xp":490,"credits":110,"badgeIds":["infinite-query"],"skillXp":{"api_design":30}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-be14-01', 1, 'mira', 'Arc II is closed. Data is trustworthy, fast, correlated. Arc III starts with a different problem: what Forge builds on top of that data for other teams to actually consume.'),
  ('mission-be14-01', 2, 'forge', 'Case in point: the mobile team. Three screens, same underlying data, three different combinations of fields each one needs. REST answered that by growing nineteen slightly-different endpoints, and counting.'),
  ('mission-be14-01', 3, 'mira', 'GraphQL exists for exactly this. One endpoint, and the client states the shape of data it needs in the request itself -- no more, no less, and no need to build a new endpoint every time a screen''s needs change slightly.'),

  ('mission-be14-02', 1, 'forge', 'The schema is the whole contract, written once, in the GraphQL Schema Definition Language. Every type, every field, every query and mutation the API allows -- if it isn''t declared here, a client can''t ask for it.'),
  ('mission-be14-02', 2, 'forge', 'Types are strict. Get a field''s type wrong in the schema and every query touching it breaks the same way, every time -- that rigidity is a feature, not the REST-style rigidity we just spent an Act escaping.'),

  ('mission-be14-03', 1, 'mira', 'An object type names a shape and lists its fields, each one typed -- a scalar like String or Int, or another object type nested inside it. Nest enough of them and you''ve modeled an actual graph, not just a flat table.'),
  ('mission-be14-03', 2, 'mira', 'A Permit type with an applicant field that''s itself a Citizen type, which has its own address field -- a client can walk that whole structure in one request, exactly as deep as it actually needs.'),

  ('mission-be14-04', 1, 'forge', 'A query mirrors the shape of the schema. Ask for exactly the fields you want, nested as deep as you need, and the response comes back in that same shape -- nothing more.'),
  ('mission-be14-04', 2, 'forge', 'One mobile screen wants a permit''s id, status, and the applicant''s name. Another wants the full applicant address too. Same schema, same endpoint, two completely different queries -- no new endpoint for either one.'),

  ('mission-be14-05', 1, 'mira', 'Everything so far has been reading. A mutation is the GraphQL way to write -- create a permit, update its status, revoke it. The schema declares mutations in their own explicit block, separate from queries.'),
  ('mission-be14-05', 2, 'mira', 'Convention matters here: a mutation usually takes one input argument shaped by its own input type, and returns the object it just changed, so the client can see the result of its own write in the same round trip.'),

  ('mission-be14-06', 1, 'forge', 'The schema is a promise. A resolver is the function that keeps it -- one per field, called with the parent object, the field''s arguments, and shared context, returning that one field''s actual value.'),
  ('mission-be14-06', 2, 'mira', 'Query permit { applicant { name } } and three resolvers run: one for permit, one for applicant using the permit it just got back as its parent, one for name using the applicant it just got back. Each resolver only has to know how to get its own field.'),

  ('mission-be14-07', 1, 'forge', 'A query with the permit id hardcoded as "482" only ever fetches permit 482. A variable turns it into a reusable query the client can send with any id, without regenerating the query string every time.'),
  ('mission-be14-07', 2, 'forge', 'Fragments solve the other repetition: the same set of fields -- id, status, applicant name -- selected in five different queries across the mobile app. Define it once as a fragment, spread it into all five.'),

  ('mission-be14-08', 1, 'mira', 'A search across permits, inspections and citations returns three genuinely different shapes. An interface works when they share some common fields -- id and status, say. A union works when they don''t share anything the client can assume without checking the type first.'),
  ('mission-be14-08', 2, 'mira', 'Either way, a client querying a polymorphic field has to ask "which concrete type actually came back" before it can safely request that type''s specific fields.'),

  ('mission-be14-09', 1, 'forge', 'permits returning every permit at once is the exact same problem the REST API had at forty thousand rows. GraphQL''s answer looks unfamiliar but it''s the same cursor idea from the REST Acts, wrapped in its own connection shape: edges, each with a node and a cursor, plus a pageInfo block.'),
  ('mission-be14-09', 2, 'forge', 'Ask for the first 20 results after a cursor and pageInfo tells you whether more exist without a second round trip just to find out.'),

  ('mission-be14-10', 1, 'mira', 'A query for 20 permits, each one resolving its own applicant field independently, fires one query to fetch the 20 permits and then 20 more -- one per permit -- to fetch each applicant. Twenty-one queries for data two queries could have returned.'),
  ('mission-be14-10', 2, 'forge', 'DataLoader fixes it by batching: instead of each Permit.applicant resolver hitting the database immediately, it queues its request for one tick, then fetches every queued applicant id in a single batched call.'),

  ('mission-be14-11', 1, 'forge', 'Authenticating a GraphQL request is the same as any API: a token, checked once, in context every resolver can read. The harder problem is new: a request that''s trivially cheap to send can still be expensive to execute, because the schema lets the client compose the depth and breadth of the query itself.'),
  ('mission-be14-11', 2, 'forge', 'A permit whose applicant has permits whose applicants have permits -- syntactically valid, nested as deep as the client wants, and nothing in a bare schema stops it from recursing until something falls over.'),

  ('mission-be14-12', 1, 'forge', 'Incident: a client, built entirely by reading our own public schema, sent a query that recurses through an applicant''s permits, each permit''s applicant, that applicant''s permits, and it didn''t stop. Server load spiked until we killed the connection manually.'),
  ('mission-be14-12', 2, 'mira', 'No exploit here -- nobody broke in, nobody guessed a hidden field. Everything they queried was public, documented, exactly as the schema describes it. That''s what makes this one worth sitting with.'),
  ('mission-be14-12', 3, 'forge', 'The schema genuinely allows an applicant to have permits, and each permit to have an applicant, all the way down. Self-referencing, and nothing about it is wrong on its own -- an applicant really does have permits, a permit really does have an applicant.'),
  ('mission-be14-12', 4, 'mira', 'Find the actual gap. Not "who''s at fault" -- there''s no one to blame here. What safeguard should have existed and didn''t.'),
  ('mission-be14-12', 5, 'forge', 'One more thing, since I know you''ll ask: I checked. This one has nothing to do with the pattern -- no doubled slash anywhere in it. Just a graph shaped exactly the way it was always going to be shaped, with nothing stopping someone from walking it forever.'),
  ('mission-be14-12', 6, 'mira', 'GraphQL solved the shape-of-data problem. It didn''t solve every problem -- and it still assumes one request gets one response, start to finish, however long that takes. The next incident won''t. Something out there needs to stream continuously, not just answer once.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-be14-01-o1', 'mission-be14-01', 1, 'Diagnose the endpoint sprawl', 'Find the evidence that explains why nineteen endpoints exist, not just that they do.'),
  ('mission-be14-02-o1', 'mission-be14-02', 1, 'Find the schema bug', 'Debug a schema definition that doesn''t match the data it''s meant to describe.'),
  ('mission-be14-03-o1', 'mission-be14-03', 1, 'Match the type system term', 'Match each GraphQL type-system term to what it actually describes.'),
  ('mission-be14-04-o1', 'mission-be14-04', 1, 'Find the invalid query', 'Debug a query that requests a field the schema never declared.'),
  ('mission-be14-05-o1', 'mission-be14-05', 1, 'Judge the mutation design', 'Decide whether this mutation follows the shape a well-designed GraphQL write should.'),
  ('mission-be14-06-o1', 'mission-be14-06', 1, 'Order the resolver chain', 'Order the resolver execution for a nested query three levels deep.'),
  ('mission-be14-07-o1', 'mission-be14-07', 1, 'Find the duplicated selection', 'Debug two queries that should share one fragment instead of repeating the same field selection.'),
  ('mission-be14-08-o1', 'mission-be14-08', 1, 'Choose interface or union', 'Decide whether each search-result scenario calls for an interface or a union.'),
  ('mission-be14-09-o1', 'mission-be14-09', 1, 'Read the connection shape', 'Find the field that tells a client whether more results exist without fetching speculatively.'),
  ('mission-be14-10-o1', 'mission-be14-10', 1, 'Diagnose the N+1', 'Find the evidence that explains the actual mechanism producing 21 queries for one request.'),
  ('mission-be14-11-o1', 'mission-be14-11', 1, 'Choose the missing safeguard', 'Pick the safeguard that actually addresses an unbounded, client-composed query.'),
  ('mission-be14-12-o1', 'mission-be14-12', 1, 'Identify the recursive field', 'Find the schema field that closes the self-referencing cycle.'),
  ('mission-be14-12-o2', 'mission-be14-12', 2, 'Rule out the wrong fixes', 'Choose the fix that actually addresses an unbounded self-referencing query.'),
  ('mission-be14-12-o3', 'mission-be14-12', 3, 'Confirm it''s not an exploit', 'Find the evidence that shows this is a missing safeguard, not misuse.'),
  ('mission-be14-12-o4', 'mission-be14-12', 4, 'Patch the gap', 'Synthesize the incident into the one safeguard that should have existed.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-be14-01-o1-c1', 'mission-be14-01-o1', 1, 'investigation', 'Which evidence explains the actual root cause of the endpoint sprawl, not just a symptom of it?', '{"evidence":[{"id":"ev1","label":"Endpoint count","detail":"19 REST endpoints exist solely to serve 3 mobile screens, several differing only in which fields they include"},{"id":"ev2","label":"Client complaint","detail":"\"Every time a screen needs one more field, we either over-fetch from an existing endpoint or someone builds a new one\""},{"id":"ev3","label":"Design note","detail":"Each REST endpoint returns a fixed, server-decided shape -- the client has no way to ask for a different combination of fields without a new endpoint"}],"question":"Which evidence explains the actual root cause of the endpoint sprawl, not just a symptom of it?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),

  ('mission-be14-02-o1-c1', 'mission-be14-02-o1', 1, 'code_debugging', 'Legacy permits sometimes have no recorded district, and querying them now throws a runtime "Cannot return null for non-nullable field Permit.district" error. Which line in the schema is responsible?', '{"language":"graphql","code":"type Permit {\n  id: ID!\n  applicantName: String!\n  status: String!\n  issuedAt: String\n  district: Int!\n}\n\ntype Query {\n  permit(id: ID!): Permit\n  permits(district: Int): [Permit!]!\n}","question":"Legacy permits sometimes have no recorded district, and querying them now throws a runtime \"Cannot return null for non-nullable field Permit.district\" error. Which line in the schema is responsible?"}'::jsonb, '{"requiredLineIds":["  district: Int!"]}'::jsonb),

  ('mission-be14-03-o1-c1', 'mission-be14-03-o1', 1, 'drag_and_drop', 'Match each GraphQL type-system term to what it actually describes.', '{"items":[{"id":"g1","text":"Scalar type"},{"id":"g2","text":"Object type"},{"id":"g3","text":"Field"},{"id":"g4","text":"Non-null modifier (!)"},{"id":"g5","text":"List modifier ([ ])"}],"targets":[{"id":"t1","label":"A primitive leaf value like String, Int, Boolean, ID"},{"id":"t2","label":"A named shape composed of fields, which can nest other object types"},{"id":"t3","label":"One named, typed piece of an object type"},{"id":"t4","label":"A guarantee this value will never be null in a valid response"},{"id":"t5","label":"A guarantee this value is an array of the wrapped type"}]}'::jsonb, '{"correctMapping":{"g1":"t1","g2":"t2","g3":"t3","g4":"t4","g5":"t5"}}'::jsonb),

  ('mission-be14-04-o1-c1', 'mission-be14-04-o1', 1, 'code_debugging', 'This query fails validation before it even reaches a resolver. Which line requests a field that was never declared on the Applicant type in the schema?', '{"language":"graphql","code":"query {\n  permit(id: \"482\") {\n    id\n    status\n    applicant {\n      name\n      internalCreditScore\n    }\n  }\n}","question":"This query fails validation before it even reaches a resolver. Which line requests a field that was never declared on the Applicant type in the schema?"}'::jsonb, '{"requiredLineIds":["      internalCreditScore"]}'::jsonb),

  ('mission-be14-05-o1-c1', 'mission-be14-05-o1', 1, 'multiple_choice', 'A proposed mutation takes id, status, district, notes and six more loose scalar arguments planned. Is this well-designed?', '{"question":"A proposed mutation is updatePermitStatus(id: \"482\", status: \"approved\", district: 4, notes: \"looks good\"), with six more loose scalar arguments planned on top. Is this well-designed?","options":[{"id":"a","text":"Yes, more arguments means more flexibility"},{"id":"b","text":"No -- as arguments grow, they should be grouped into a single structured input type instead of piling up as separate loose scalar arguments"},{"id":"c","text":"No, mutations should never take arguments at all"},{"id":"d","text":"Yes, as long as every argument is optional"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be14-06-o1-c1', 'mission-be14-06-o1', 1, 'interactive_diagram', 'Order the resolver execution for the nested query permit { applicant { name } }.', '{"diagramId":"resolver-execution-chain","hotspots":[{"id":"resolve_permit","label":"Resolve Query.permit","explanation":"Runs first, with no parent -- fetches the permit by its id argument."},{"id":"pass_parent","label":"Permit object becomes the parent","explanation":"Whatever Query.permit returned is passed as the parent argument to the next resolver down."},{"id":"resolve_applicant","label":"Resolve Permit.applicant","explanation":"Uses the permit (its parent) to fetch the applicant it belongs to."},{"id":"resolve_name","label":"Resolve Applicant.name","explanation":"Uses the applicant (its parent) to return just the name field."}],"task":"Order the resolver execution for the nested query permit { applicant { name } }."}'::jsonb, '{"correctOrderIds":["resolve_permit","pass_parent","resolve_applicant","resolve_name"]}'::jsonb),

  ('mission-be14-07-o1-c1', 'mission-be14-07-o1', 1, 'code_debugging', 'These two queries repeat the exact same field selection. Which line is the duplicated selection that should be pulled into a shared fragment instead?', '{"language":"graphql","code":"query GetPermitForList {\n  permit(id: \"482\") {\n    id\n    status\n    applicant { name }\n  }\n}\n\nquery GetPermitForDetail {\n  permit(id: \"482\") {\n    id\n    status\n    applicant { name }\n    issuedAt\n  }\n}","question":"These two queries repeat the exact same field selection. Which line is the duplicated selection that should be pulled into a shared fragment instead?"}'::jsonb, '{"requiredLineIds":["    applicant { name }"]}'::jsonb),

  ('mission-be14-08-o1-c1', 'mission-be14-08-o1', 1, 'drag_and_drop', 'Decide whether each search-result scenario calls for an interface or a union.', '{"items":[{"id":"i1","text":"Permits, inspections and citations all share id, status and createdAt, but each has fields unique to itself"},{"id":"i2","text":"A search result could be a Permit or a completely unrelated NewsAnnouncement type, with nothing meaningfully shared between them"},{"id":"i3","text":"Every result type needs a common summary field so a list view can render any of them identically"},{"id":"i4","text":"A field can return either a SuccessResult or an ErrorResult, and the two have no fields in common at all"}],"targets":[{"id":"t1","label":"Interface (shared fields across types)"},{"id":"t2","label":"Union (no shared fields required)"}]}'::jsonb, '{"correctMapping":{"i1":"t1","i2":"t2","i3":"t1","i4":"t2"}}'::jsonb),

  ('mission-be14-09-o1-c1', 'mission-be14-09-o1', 1, 'code_debugging', 'A client needs to know whether more results exist without fetching another page speculatively. Which line answers that directly?', '{"language":"graphql","code":"query {\n  permits(first: 20, after: \"cursor_482\") {\n    edges {\n      cursor\n      node {\n        id\n        status\n      }\n    }\n    pageInfo {\n      hasNextPage\n      endCursor\n    }\n  }\n}","question":"A client needs to know whether more results exist without fetching another page speculatively. Which line answers that directly?"}'::jsonb, '{"requiredLineIds":["      hasNextPage"]}'::jsonb),

  ('mission-be14-10-o1-c1', 'mission-be14-10-o1', 1, 'investigation', 'Which evidence explains the actual mechanism producing 21 separate queries, not just the symptom of it being slow?', '{"evidence":[{"id":"ev1","label":"Query log","detail":"1 query for permits, followed immediately by 20 near-identical queries, each selecting one applicant by a different id"},{"id":"ev2","label":"Resolver code","detail":"Permit.applicant resolver runs a database query for one applicant every time it''s called, with no batching or caching"},{"id":"ev3","label":"Response time","detail":"The query for 20 permits now takes 640ms, up from 40ms with 5 permits"}],"question":"Which evidence explains the actual mechanism producing 21 separate queries, not just the symptom of it being slow?"}'::jsonb, '{"requiredEvidenceIds":["ev2"]}'::jsonb),

  ('mission-be14-11-o1-c1', 'mission-be14-11-o1', 1, 'multiple_choice', 'A schema is fully typed and correctly authenticated, but has no limit on how deep or complex a client-composed query can get. Which safeguard actually addresses that specific gap?', '{"question":"A schema is fully typed and correctly authenticated, but has no limit on how deep or how complex a client-composed query can get. Which safeguard actually addresses that specific gap?","options":[{"id":"a","text":"Rate limiting requests per minute"},{"id":"b","text":"Query depth limiting or cost-based complexity analysis, rejecting a query before execution if it exceeds a configured depth or computed cost"},{"id":"c","text":"Requiring HTTPS on every request"},{"id":"d","text":"Adding more database indexes"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-be14-12-o1-c1', 'mission-be14-12-o1', 1, 'code_debugging', 'Which line, combined with Permit.applicant, forms the self-referencing cycle a query can walk without ever hitting a natural end?', '{"language":"graphql","code":"type Permit {\n  id: ID!\n  status: String!\n  applicant: Applicant!\n}\n\ntype Applicant {\n  id: ID!\n  name: String!\n  permits: [Permit!]!\n}","question":"Which line, combined with Permit.applicant, forms the self-referencing cycle a query can walk without ever hitting a natural end?"}'::jsonb, '{"requiredLineIds":["  permits: [Permit!]!"]}'::jsonb),
  ('mission-be14-12-o2-c1', 'mission-be14-12-o2', 1, 'multiple_choice', 'Which of these proposed fixes actually addresses an unbounded self-referencing query, rather than a different problem entirely?', '{"question":"Which of these proposed fixes actually addresses an unbounded self-referencing query, rather than a different problem entirely?","options":[{"id":"a","text":"Add an index on the applicant lookup column"},{"id":"b","text":"Require authentication on every field"},{"id":"c","text":"Enforce a maximum query depth, or a computed complexity budget, and reject anything over it before execution"},{"id":"d","text":"Increase the server''s memory allocation"}]}'::jsonb, '{"correctOptionId":"c"}'::jsonb),
  ('mission-be14-12-o3-c1', 'mission-be14-12-o3', 1, 'investigation', 'Which evidence best shows this is a missing safeguard, not an exploit or misuse?', '{"evidence":[{"id":"ev1","label":"Client source","detail":"The offending client was built entirely from the publicly documented schema, with no attempt to access anything undocumented"},{"id":"ev2","label":"Auth log","detail":"The client authenticated normally with a valid, unmodified API token"},{"id":"ev3","label":"Query shape","detail":"The recursive query alternates between two legitimately-declared fields, Permit.applicant and Applicant.permits, with no depth argument or limit anywhere in the schema to stop it"}],"question":"Which evidence best shows this is a missing safeguard, not an exploit or misuse?"}'::jsonb, '{"requiredEvidenceIds":["ev3"]}'::jsonb),
  ('mission-be14-12-o4-c1', 'mission-be14-12-o4', 1, 'boss_encounter', 'Having found the cycle, ruled out the wrong fixes, and confirmed this was never an exploit, state the one safeguard that would have prevented it.', '{"stages":[{"objectiveRef":"mission-be14-12-o1","label":"Identify the recursive field"},{"objectiveRef":"mission-be14-12-o2","label":"Rule out the wrong fixes"},{"objectiveRef":"mission-be14-12-o3","label":"Confirm it''s not an exploit"}],"task":"Having found the cycle, ruled out the wrong fixes, and confirmed this was never an exploit, state the one safeguard that would have prevented it: enforce a maximum query depth or a computed complexity budget at validation time, rejecting an over-deep or over-expensive query before a single resolver runs. GraphQL solved the shape-of-data problem -- it never claimed to solve the shape of every request a client could compose."}'::jsonb, '{"requiredObjectiveIds":["mission-be14-12-o1","mission-be14-12-o2","mission-be14-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-be14-01-o1-c1', 'orientation', 'Count and complaint are both symptoms of the same underlying constraint.', 10, 1),
  ('mission-be14-01-o1-c1', 'concept', 'A REST endpoint''s response shape is fixed by the server, chosen in advance -- the client can''t negotiate it per request, only pick from what already exists.', 20, 2),
  ('mission-be14-01-o1-c1', 'solution', 'ev3: because each endpoint''s shape is fixed by the server in advance, every new combination of fields a client needs becomes a reason to either over-fetch or build a new endpoint. That''s the root cause.', 30, 3),

  ('mission-be14-02-o1-c1', 'orientation', 'A "!" in the schema isn''t documentation -- it''s a runtime guarantee the server has to keep or the query fails outright.', 10, 1),
  ('mission-be14-02-o1-c1', 'concept', 'Marking a field non-null promises every resolved value will have it. If even one real record can legitimately lack it, the field was declared too strictly.', 20, 2),
  ('mission-be14-02-o1-c1', 'solution', 'district: Int! promises every permit has a district. Legacy permits don''t, so the resolver returns null for a field the schema swore couldn''t be null -- it should be a nullable district: Int.', 30, 3),

  ('mission-be14-03-o1-c1', 'orientation', 'One of these is a leaf value. One is a composite shape. Three are modifiers layered on top of a type.', 10, 1),
  ('mission-be14-03-o1-c1', 'concept', 'Scalars are where nesting stops. Object types are where it continues. The two modifiers are independent -- a field can be a required list, a list of required items, or any combination.', 20, 2),
  ('mission-be14-03-o1-c1', 'solution', 'Scalar -> primitive leaf value. Object type -> named nestable shape. Field -> one typed member of a shape. ! -> never null. [ ] -> a list of the wrapped type.', 30, 3),

  ('mission-be14-04-o1-c1', 'orientation', 'GraphQL validates a query against the schema before running a single resolver -- an undeclared field never gets the chance to execute.', 10, 1),
  ('mission-be14-04-o1-c1', 'concept', 'Every field in a query has to exist on the type it''s selected from in the schema, exactly -- there''s no equivalent of a REST client just ignoring fields it doesn''t recognize.', 20, 2),
  ('mission-be14-04-o1-c1', 'solution', 'internalCreditScore was never declared on the Applicant type -- the query fails validation before execution, which is exactly the safety a fixed REST response shape doesn''t give you for free.', 30, 3),

  ('mission-be14-05-o1-c1', 'orientation', 'A handful of loose scalar arguments is fine. A growing pile of them is a design smell you''ve seen before, just in a new syntax.', 10, 1),
  ('mission-be14-05-o1-c1', 'concept', 'This is the same instinct as a DTO from the REST Acts: give a write operation one deliberate, named, structured shape instead of an ever-growing argument list.', 20, 2),
  ('mission-be14-05-o1-c1', 'solution', 'b: group the arguments into a single input type, e.g. updatePermitStatus(input: UpdatePermitStatusInput!) -- the same discipline a REST DTO enforces, expressed in GraphQL.', 30, 3),

  ('mission-be14-06-o1-c1', 'orientation', 'Nothing can resolve a nested field until the object it belongs to has already been resolved.', 10, 1),
  ('mission-be14-06-o1-c1', 'concept', 'Each resolver receives the previous resolver''s return value as its parent argument -- that''s the entire mechanism nested fields run on.', 20, 2),
  ('mission-be14-06-o1-c1', 'solution', 'Resolve permit first, its result becomes the parent for the applicant resolver, whose result becomes the parent for the name resolver.', 30, 3),

  ('mission-be14-07-o1-c1', 'orientation', 'Read both queries field by field -- three of them are identical in both.', 10, 1),
  ('mission-be14-07-o1-c1', 'concept', 'Anything selected identically in more than one query is a fragment candidate: define it once as a fragment on the relevant type, then spread it into both queries.', 20, 2),
  ('mission-be14-07-o1-c1', 'solution', 'id, status, and applicant { name } are selected identically in both queries -- applicant { name } in particular is exactly what a shared fragment should replace.', 30, 3),

  ('mission-be14-08-o1-c1', 'orientation', 'Ask one question: do these types have any fields genuinely in common, or are they just different things that can show up in the same slot?', 10, 1),
  ('mission-be14-08-o1-c1', 'concept', 'An interface is a contract the implementing types agree to keep. A union just says "one of these," with no shared contract implied at all.', 20, 2),
  ('mission-be14-08-o1-c1', 'solution', 'Shared fields (id/status/createdAt, or a common summary field) -> interface. Genuinely unrelated shapes with nothing in common -> union.', 30, 3),

  ('mission-be14-09-o1-c1', 'orientation', 'The answer lives in the block whose whole job is describing the page itself, not the results in it.', 10, 1),
  ('mission-be14-09-o1-c1', 'concept', 'pageInfo exists specifically so a client never has to guess whether a page was the last one -- hasNextPage answers it in the same response as the results.', 20, 2),
  ('mission-be14-09-o1-c1', 'solution', 'hasNextPage inside pageInfo tells the client directly whether to request another page -- no speculative extra request needed.', 30, 3),

  ('mission-be14-10-o1-c1', 'orientation', 'Slow response time and a long query log are both symptoms. One piece of evidence explains why the resolver behaves that way at all.', 10, 1),
  ('mission-be14-10-o1-c1', 'concept', 'Each field resolver runs independently by design -- without something batching those calls together, N independent parent objects means N independent fetches for the same child field.', 20, 2),
  ('mission-be14-10-o1-c1', 'solution', 'ev2: the applicant resolver hits the database independently every single time it runs, with nothing batching those calls -- that''s the actual mechanism behind the 21 queries, not just the resulting slowness.', 30, 3),

  ('mission-be14-11-o1-c1', 'orientation', 'The gap isn''t about how often a client asks, or how the request travels -- it''s about how expensive one single request is allowed to be.', 10, 1),
  ('mission-be14-11-o1-c1', 'concept', 'Rate limiting caps request count. Depth and complexity limiting caps how much any one request is allowed to demand, before a single resolver runs.', 20, 2),
  ('mission-be14-11-o1-c1', 'solution', 'b: depth limiting or complexity analysis rejects an over-deep or over-expensive query at validation time, before it ever reaches a resolver -- the other options don''t touch the actual gap.', 30, 3),

  ('mission-be14-12-o1-c1', 'orientation', 'Follow one field, then follow the field it leads to, then check whether you''re back where you started.', 10, 1),
  ('mission-be14-12-o1-c1', 'concept', 'A cycle doesn''t require anything malformed -- two fields, each individually correct, can still point at each other forever.', 20, 2),
  ('mission-be14-12-o1-c1', 'solution', 'permits: [Permit!]! on Applicant closes the loop with Permit.applicant -- together they form a cycle with no natural stopping point.', 30, 3),
  ('mission-be14-12-o2-c1', 'orientation', 'Ask which of these actually changes how deep or expensive a single query is allowed to be, versus everything else.', 10, 1),
  ('mission-be14-12-o2-c1', 'solution', 'c: a maximum query depth or complexity budget, enforced before execution, is the only option that actually limits how far a self-referencing query can recurse.', 20, 2),
  ('mission-be14-12-o3-c1', 'orientation', 'An exploit implies unauthorized access or hidden behavior. Check whether anything here was either.', 10, 1),
  ('mission-be14-12-o3-c1', 'concept', 'A valid token, a publicly documented schema, and two legitimately declared fields being walked back and forth -- none of that is misuse. It''s a gap in what the schema itself allowed.', 20, 2),
  ('mission-be14-12-o3-c1', 'solution', 'ev3: the query only ever touches two legitimately-declared, publicly documented fields, with nothing in the schema limiting how many times they can alternate -- that''s a missing safeguard, not an exploit.', 30, 3),
  ('mission-be14-12-o4-c1', 'orientation', 'Look at what would have stopped this cycle at the door, before it ever reached a resolver.', 15, 1),
  ('mission-be14-12-o4-c1', 'solution', 'A maximum query depth or complexity budget, enforced at validation time -- the same fix confirmed correct in the previous objective, now stated as the rule going forward.', 25, 2);
